// Webhook v2 envolve o payload em .body — suporta os dois formatos
const raw = $input.first().json;
const d = raw.body || raw;

if (!d.question || String(d.question).trim().length < 3) {
  throw new Error('question é obrigatório (mínimo 3 caracteres)');
}

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

return [{
  json: {
    conversationId: d.conversationId || uuid(),
    isNewConversation: !d.conversationId,
    question: String(d.question).trim(),
    folderIds: Array.isArray(d.folderIds) ? d.folderIds : [],
    mode: d.mode || 'rapido',
    userId: d.userId || null,
    artifactOutline: d.artifactOutline || '',
    artifactBodies: d.artifactBodies || '',
    // === CONFIGS SUPABASE (usadas no HTTP: Busca Chunks) ===
    supabaseUrl: 'https://alrnajijumqvxzmogwpy.supabase.co',
    supabaseServiceKey: '***REMOVIDO***',
  }
}];

const d = $input.first().json;
const mode = d.mode;

const topK      = mode === 'pesquisa' ? 18 : 4;
const maxTokens = mode === 'pesquisa' ? 2600 : 700;

const modeGuidance = mode === 'pesquisa'
  ? 'MODO PESQUISA: você recebeu trechos de várias buscas relacionadas. ' +
    'Compare o que as fontes dizem, aponte convergências e divergências, e ' +
    'organize em seções com subtítulos. Quando duas fontes discordarem, ' +
    'mostre as duas em vez de escolher uma em silêncio.'
  : 'MODO RÁPIDO: responda em até 4 parágrafos curtos, direto ao ponto. ' +
    'Sem introdução, sem recapitular a pergunta. Se o assunto for mais ' +
    'profundo do que cabe aqui, diga numa linha que vale usar o modo pesquisa.';

return [{ json: { ...d, topK, maxTokens, minSimilarity: 0.4, modeGuidance } }];

// runOnceForAllItems — roda mesmo com 0 mensagens de histórico
const cfg = $('Code: Modo & Configs').first().json;

// Histórico: itens nativos do Supabase; alwaysOutputData gera item vazio se vazio
const historyItems = $input.all().map(i => i.json).filter(m => m.role);

// Chunks: vêm como texto (responseFormat: text) do HTTP: Busca Chunks
let chunks;
try { chunks = JSON.parse($('HTTP: Busca Chunks').first().json.body || '[]'); } catch(e) { chunks = []; }
if (!Array.isArray(chunks)) chunks = [];

// Contexto numerado para o LLM — [1] Título (página X)\nconteúdo
const context = chunks.length
  ? chunks.map((c, i) => {
      const page = c.page ? ' (página ' + c.page + ')' : '';
      return '[' + (i + 1) + '] ' + (c.title || 'Documento') + page + '\n' + c.content;
    }).join('\n\n---\n\n')
  : 'Nenhum documento encontrado.';

// Contexto do documento de diagnóstico (enviado pelo frontend)
const artifactState = cfg.artifactOutline
  ? '\n\nDOCUMENTO ATUAL (sumário):\n' + cfg.artifactOutline +
    (cfg.artifactBodies ? '\n\nCONTEÚDO INTEGRAL DAS SEÇÕES RELEVANTES:\n' + cfg.artifactBodies : '')
  : '';

// Histórico formatado (cronológico)
const historyText = historyItems.length
  ? '\n\n--- Histórico ---\n' +
    historyItems.map(m => (m.role === 'user' ? 'Usuário' : 'Assistente') + ': ' + m.content).join('\n') +
    '\n--- Fim do histórico ---'
  : '';

return [{
  json: {
    question: cfg.question,
    systemPromptWithContext:
      cfg.systemPrompt + '\n\n' + cfg.modeGuidance + historyText +
      '\n\nTrechos dos documentos:\n\n' + context + artifactState,
    chunks,
    conversationId: cfg.conversationId,
    userId: cfg.userId,
    mode: cfg.mode,
    supabaseUrl: cfg.supabaseUrl,
    supabaseServiceKey: cfg.supabaseServiceKey,
  }
}];

const answer = $input.item.json.output || '';
const ctx = $('Code: Monta Prompt').first().json;
const chunks = ctx.chunks || [];

// Quais marcadores [N] aparecem na resposta
const usedMarkers = new Set();
for (const m of [...(answer.matchAll(/\[(\d{1,2})\]/g) || [])]) {
  usedMarkers.add(parseInt(m[1]));
}

// Apenas os chunks citados no texto
const citations = chunks
  .map((c, i) => ({ c, marker: i + 1 }))
  .filter(({ marker }) => usedMarkers.has(marker))
  .map(({ c, marker }) => ({
    id: c.id,
    sourceType: c.source_type || 'document',
    title: c.title || '',
    detail: c.page ? 'Página ' + c.page : (c.folder_name || ''),
    relevance: Math.round((c.similarity || 0) * 100) / 100,
    snippet: (c.content || '').slice(0, 320),
    reference: c.reference || null,
    marker,
    documentId: c.document_id || null,
    folderId: c.folder_id || null,
    folderName: c.folder_name || null,
    page: c.page || null,
  }));

// Confidence: melhor similaridade + quantidade de chunks fortes (>= 0.4)
const similarities = chunks.map(c => c.similarity || 0).sort((a, b) => b - a);
const top    = similarities[0] ?? 0;
const strong = similarities.filter(s => s >= 0.4).length;
const level  = (top >= 0.55 && strong >= 2) ? 'muito_alta'
             : top >= 0.5  ? 'alta'
             : top >= 0.4  ? 'media'
             : 'baixa';

return [{
  json: {
    conversationId: ctx.conversationId,
    userId: ctx.userId,
    question: ctx.question,
    answer,
    citations,
    confidence: { level, score: Math.round(top * 100) / 100 },
    supabaseUrl: ctx.supabaseUrl,
    supabaseServiceKey: ctx.supabaseServiceKey,
    mode: ctx.mode,
  }
}];
